(4378236, 629882, 68586, '<td valign="top">Very stylish shot</td>', 'Very stylish shot', '2008-01-09 15:19:18.000000', NULL, 1),
(4378238, 630724, 77543, '<td valign="top">The shadows are too harsh.</td>', 'The shadows are too harsh.', '2008-01-09 15:19:25.000000', NULL, 1),
