(4378247, 629529, 77543, '<td valign="top">It''s blurred</td>', 'It''s blurred', '2008-01-09 15:20:42.000000', NULL, 1),
(4378261, 629865, 77543, '<td valign="top">I like the simplicity of the dark hat and glasses. I think it would have been stronger if you''d cropped much tighter to show only the face and hat.</td>', 'I like the simplicity of the dark hat and glasses. I think it would have been stronger if you''d cropped much tighter to show only the face and hat.', '2008-01-09 15:22:39.000000', NULL, 1),
(4378267, 628976, 77543, '<td valign="top">It would be better without the cushions.</td>', 'It would be better without the cushions.', '2008-01-09 15:23:54.000000', NULL, 1),
(4378272, 629497, 77543, '<td valign="top">The face is too dark.</td>', 'The face is too dark.', '2008-01-09 15:24:33.000000', NULL, 1),
(4378279, 630614, 77543, '<td valign="top">I''d like to see a bit more of his hands and to have them in focus with more depth of field.</td>', 'I''d like to see a bit more of his hands and to have them in focus with more depth of field.', '2008-01-09 15:25:24.000000', NULL, 1),
(4378288, 630805, 77543, '<td valign="top">I''d crop a bit closer to remove the background in the top right of the frame and the relatively large area of chest.</td>', 'I''d crop a bit closer to remove the background in the top right of the frame and the relatively large area of chest.', '2008-01-09 15:26:39.000000', NULL, 1),
(4378296, 630248, 77543, '<td valign="top">The light is too harsh and the post in the background shouldn''t be there. It looks like you could have moved the subject slightly to avoid the wooden post.</td>', 'The light is too harsh and the post in the background shouldn''t be there. It looks like you could have moved the subject slightly to avoid the wooden post.', '2008-01-09 15:27:54.000000', NULL, 1),
(4378299, 629820, 77543, '<td valign="top">I''d have rotated the glasses through 90 degrees.</td>', 'I''d have rotated the glasses through 90 degrees.', '2008-01-09 15:28:30.000000', NULL, 1),
(4378306, 630270, 77543, '<td valign="top">This is very dark and flat.</td>', 'This is very dark and flat.', '2008-01-09 15:29:48.000000', NULL, 1),
(4378311, 630697, 77543, '<td valign="top">A very nice silhouette.</td>', 'A very nice silhouette.', '2008-01-09 15:30:38.000000', NULL, 1),
(4378318, 630327, 77543, '<td valign="top">It''s nicely cropped with a good diagonal. It could be a bit sharper.</td>', 'It''s nicely cropped with a good diagonal. It could be a bit sharper.', '2008-01-09 15:31:32.000000', NULL, 1),
(4378327, 630714, 77543, '<td valign="top">It''s a bit flat and lacking in contrast. Nice plain background, though.</td>', 'It''s a bit flat and lacking in contrast. Nice plain background, though.', '2008-01-09 15:33:08.000000', NULL, 1),
(4378331, 630244, 77543, '<td valign="top">It''s bold to shoot a portrait with a wide angle. Loose the red in the background.</td>', 'It''s bold to shoot a portrait with a wide angle. Loose the red in the background.', '2008-01-09 15:34:04.000000', NULL, 1),
(4378341, 630470, 77543, '<td valign="top">This image has been posted too small - it is only 400 pixels high instead of 640. Because of that it looses some impact.<br/> <br/>Otherwise the only real problem is the tree on the right - that could have been removed by cropping.</td>', 'This image has been posted too small - it is only 400 pixels high instead of 640. Because of that it looses some impact. Otherwise the only real problem is the tree on the right - that could have been removed by cropping.', '2008-01-09 15:36:07.000000', NULL, 1),
(4378363, 630077, 71608, '<td valign="top">Lovely use of depth-of-field, and I love the window lighting :)</td>', 'Lovely use of depth-of-field, and I love the window lighting :)', '2008-01-09 15:40:28.000000', NULL, 1),
(4378373, 630646, 77543, '<td valign="top">Quite effective use of narrow depth of field but the focus on the eye needs to be much sharper. It looks like the focus is on the edge of the glasses.</td>', 'Quite effective use of narrow depth of field but the focus on the eye needs to be much sharper. It looks like the focus is on the edge of the glasses.', '2008-01-09 15:44:35.000000', NULL, 1),
(4378376, 630813, 77543, '<td valign="top">Very good lighting and composition.</td>', 'Very good lighting and composition.', '2008-01-09 15:45:11.000000', NULL, 1),
(4378380, 630517, 71608, '<td valign="top">The crop is a little unsettling for me... I think including the chin would have helped :)</td>', 'The crop is a little unsettling for me... I think including the chin would have helped :)', '2008-01-09 15:46:30.000000', NULL, 1),
(4378382, 629645, 77543, '<td valign="top">Good colour contrast between the green and the face. As you''ve decided to show less than the whole face I think I''d have cropped exactly in half.</td>', 'Good colour contrast between the green and the face. As you''ve decided to show less than the whole face I think I''d have cropped exactly in half.', '2008-01-09 15:46:52.000000', NULL, 1),
(4378384, 628810, 77543, '<td valign="top">The face seems to be much too over-exposed except for the area around the eye - odd.</td>', 'The face seems to be much too over-exposed except for the area around the eye - odd.', '2008-01-09 15:48:35.000000', NULL, 1),
(4378387, 630437, 77543, '<td valign="top">It''s slightly under-exposed - probably because of the bright white area in the background.</td>', 'It''s slightly under-exposed - probably because of the bright white area in the background.', '2008-01-09 15:49:45.000000', NULL, 1),
(4378396, 630800, 77543, '<td valign="top">It seems soft - lack of sharpness.</td>', 'It seems soft - lack of sharpness.', '2008-01-09 15:52:51.000000', NULL, 1),
(4378398, 630696, 77543, '<td valign="top">The first thing I noticed was the glasses have been cut off. Also, it''s not very sharp.</td>', 'The first thing I noticed was the glasses have been cut off. Also, it''s not very sharp.', '2008-01-09 15:53:48.000000', NULL, 1),
(4378399, 629211, 77543, '<td valign="top">The face is over-exposed on the left of the frame and merges into the background.</td>', 'The face is over-exposed on the left of the frame and merges into the background.', '2008-01-09 15:54:21.000000', NULL, 1),
(4378404, 630773, 77543, '<td valign="top">There seems to be too little "depth" in this picture.</td>', 'There seems to be too little "depth" in this picture.', '2008-01-09 15:55:52.000000', NULL, 1),
(4378410, 630707, 77543, '<td valign="top">Nice and crisp. I just wonder whether a different crop would have looked better.</td>', 'Nice and crisp. I just wonder whether a different crop would have looked better.', '2008-01-09 15:57:41.000000', NULL, 1),
(4378419, 630735, 77543, '<td valign="top">Why is there no detail in the hair?</td>', 'Why is there no detail in the hair?', '2008-01-09 15:59:52.000000', NULL, 1),
