(4378561, 628708, 3102, '<td valign="top">Wow.  There are some serious quality issues here.</td>', 'Wow.  There are some serious quality issues here.', '2008-01-09 16:47:08.000000', NULL, 1),
(4378562, 630638, 77543, '<td valign="top">Wouldn''t it be better to put the camera on a tripod and use a remote control or timer.<br/> <br/>There''s too much going on in the background.</td>', 'Wouldn''t it be better to put the camera on a tripod and use a remote control or timer. There''s too much going on in the background.', '2008-01-09 16:47:17.000000', NULL, 1),
(4378563, 630168, 41864, '<td valign="top">lovely shot. find fringe a little distracting though. fab eyes.</td>', 'lovely shot. find fringe a little distracting though. fab eyes.', '2008-01-09 16:47:18.000000', NULL, 1),
