(4381571, 630544, 77543, '<td valign="top">The eye is very sharp. The sweep of hair would have been better if it completely obscured the other eye.</td>', 'The eye is very sharp. The sweep of hair would have been better if it completely obscured the other eye.', '2008-01-10 14:00:18.000000', NULL, 1),
(4381575, 630702, 77543, '<td valign="top">Nice bold shapes.</td>', 'Nice bold shapes.', '2008-01-10 14:02:38.000000', NULL, 1),
(4381612, 629314, 77543, '<td valign="top">Nice effect on the face - pity the background is so busy.</td>', 'Nice effect on the face - pity the background is so busy.', '2008-01-10 14:18:17.000000', NULL, 1),
(4381613, 629197, 77543, '<td valign="top">There''s a tiny bit of glare on the lenses. The background is a bit cluttered - perhaps en even closer cop would help.</td>', 'There''s a tiny bit of glare on the lenses. The background is a bit cluttered - perhaps en even closer cop would help.', '2008-01-10 14:19:14.000000', NULL, 1),
(4381617, 630342, 77543, '<td valign="top">I''d like to see the eyes. There is a tiny bit of red/brown in the background at the bottom that I''d remove by cropping.</td>', 'I''d like to see the eyes. There is a tiny bit of red/brown in the background at the bottom that I''d remove by cropping.', '2008-01-10 14:20:18.000000', NULL, 1),
(4381621, 630042, 77543, '<td valign="top">Slightly over-exposed on the right but nice composition.</td>', 'Slightly over-exposed on the right but nice composition.', '2008-01-10 14:20:51.000000', NULL, 1),
(4381627, 630804, 77543, '<td valign="top">The hand is over-exposed. The rim of the glasses only just miss the pupils. The background works quite well here.</td>', 'The hand is over-exposed. The rim of the glasses only just miss the pupils. The background works quite well here.', '2008-01-10 14:22:09.000000', NULL, 1),
(4381631, 630076, 77543, '<td valign="top">Nice simple background. The framing is good. I don''t like the condensation in the glasses. The picture could do with more contrast.</td>', 'Nice simple background. The framing is good. I don''t like the condensation in the glasses. The picture could do with more contrast.', '2008-01-10 14:23:59.000000', NULL, 1),
(4381635, 629684, 77543, '<td valign="top">The subject is out of focus.</td>', 'The subject is out of focus.', '2008-01-10 14:24:46.000000', NULL, 1),
(4381638, 630740, 77543, '<td valign="top">The composition is good. The highlights are too strong. I think it needs backlighting to provide some outline for the subject.</td>', 'The composition is good. The highlights are too strong. I think it needs backlighting to provide some outline for the subject.', '2008-01-10 14:26:15.000000', NULL, 1),
(4381640, 630420, 5364, '<td valign="top">Had the potential to be a great image but it''s just not sharp - did you sharpen it after resizing?</td>', 'Had the potential to be a great image but it''s just not sharp - did you sharpen it after resizing?', '2008-01-10 14:26:41.000000', NULL, 1),
(4381642, 629904, 77543, '<td valign="top">:-) The lighting and background are good. It''s well exposed but it''s not as sharp as it could be.</td>', ':-) The lighting and background are good. It''s well exposed but it''s not as sharp as it could be.', '2008-01-10 14:27:17.000000', NULL, 1),
(4381647, 630646, 5364, '<td valign="top">Could have done with some part of this being in focus - preferably the closest eye</td>', 'Could have done with some part of this being in focus - preferably the closest eye', '2008-01-10 14:29:07.000000', NULL, 1),
(4381654, 630277, 77543, '<td valign="top">Good use of natural light.</td>', 'Good use of natural light.', '2008-01-10 14:30:53.000000', NULL, 1),
(4381656, 630624, 77543, '<td valign="top">It looks a bit washed out. It needs more contrast.</td>', 'It looks a bit washed out. It needs more contrast.', '2008-01-10 14:31:22.000000', NULL, 1),
(4381657, 630232, 5364, '<td valign="top">It''s a good photo but she has striking eyes so I think you should have been much closer on here face.</td>', 'It''s a good photo but she has striking eyes so I think you should have been much closer on here face.', '2008-01-10 14:31:31.000000', NULL, 1),
