(4381783, 629778, 83845, '<td valign="top">finally something different.  love it!</td>', 'finally something different.  love it!', '2008-01-10 15:09:58.000000', NULL, 1),
(4381784, 630799, 83845, '<td valign="top">I love what the spotlight is doing for the face, but not so much what it''s doing for the spectacles.  Overall still one of the better ones I''ve seen so far.</td>', 'I love what the spotlight is doing for the face, but not so much what it''s doing for the spectacles.  Overall still one of the better ones I''ve seen so far.', '2008-01-10 15:11:32.000000', NULL, 1),
