(4381812, 629978, 83845, '<td valign="top">i love the black textures surrounding her face.</td>', 'i love the black textures surrounding her face.', '2008-01-10 15:21:30.000000', NULL, 1),
(4381815, 629214, 5364, '<td valign="top">Whay did you chop the top of your head off? Otherwise a quality photo</td>', 'Whay did you chop the top of your head off? Otherwise a quality photo', '2008-01-10 15:23:05.000000', NULL, 1),
(4381817, 629072, 83845, '<td valign="top">not sure about the composition... but like the look in his eye.  nice title.</td>', 'not sure about the composition... but like the look in his eye.  nice title.', '2008-01-10 15:23:48.000000', NULL, 1),
