INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4389209, 630470, 83313, '<td valign="top">NO! You can''t have the brown! It''s mine I say, MINE!!!<br/> <br/>The blur would have worked a bit better if her face on the left was not in the blur. Actually, at first glance I thought this was in a car. Now I see she is against a tree.</td>', 'NO! You can''t have the brown! It''s mine I say, MINE!!! The blur would have worked a bit better if her face on the left was not in the blur. Actually, at first glance I thought this was in a car. Now I see she is against a tree.', '2008-01-13 14:44:24.000000', NULL, 1),
(4389217, 630628, 83313, '<td valign="top">A fun one. I like the strong colors and the toungue. I can see through her glasses and here eyes just a little. I think either the glasses needed to be darkened so here eyes are not seen, or lightened up so they are more visible. As they are, it is mildly distracting and changes the view of the image once you notice they eyeballs. Still worth a good 6.</td>', 'A fun one. I like the strong colors and the toungue. I can see through her glasses and here eyes just a little. I think either the glasses needed to be darkened so here eyes are not seen, or lightened up so they are more visible. As they are, it is mildly distracting and changes the view of the image once you notice they eyeballs. Still worth a good 6.', '2008-01-13 14:47:59.000000', NULL, 1),
(4389223, 630437, 83313, '<td valign="top">I''m not caring for this one. The tip of the cigar is more in focus than the person. The comp is good, though.</td>', 'I''m not caring for this one. The tip of the cigar is more in focus than the person. The comp is good, though.', '2008-01-13 14:49:44.000000', NULL, 1),
(4389227, 629684, 83313, '<td valign="top">Ummm. I think the may have done better with a pretty woman in this pose. What are the ladies thinking of it?</td>', 'Ummm. I think the may have done better with a pretty woman in this pose. What are the ladies thinking of it?', '2008-01-13 14:50:56.000000', NULL, 1),
(4389230, 629001, 83313, '<td valign="top">The background is a little distracting from the subject. Not sure I really care for the look on his face.</td>', 'The background is a little distracting from the subject. Not sure I really care for the look on his face.', '2008-01-13 14:52:57.000000', NULL, 1),
(4389234, 630741, 83313, '<td valign="top">I really like that you used the reflection instead of trying to get rid of it. A touch more of the left side of his face might have been good, but it''s good work, regardless of my minor quibble.</td>', 'I really like that you used the reflection instead of trying to get rid of it. A touch more of the left side of his face might have been good, but it''s good work, regardless of my minor quibble.', '2008-01-13 14:54:44.000000', NULL, 1),
(4389241, 630692, 83313, '<td valign="top">Colors in the face seem a little washed out. I like the fact that you tried to use the reflections, instead of avoiding them, but the house across the street just doesn''t work.</td>', 'Colors in the face seem a little washed out. I like the fact that you tried to use the reflections, instead of avoiding them, but the house across the street just doesn''t work.', '2008-01-13 14:57:13.000000', NULL, 1),
(4389246, 628780, 83313, '<td valign="top">I love the snarl on his face. Other than a little shake visible  on the edges of the fingers, this is great. Making it a fave.</td>', 'I love the snarl on his face. Other than a little shake visible  on the edges of the fingers, this is great. Making it a fave.', '2008-01-13 14:59:30.000000', NULL, 1),
(4389247, 629788, 75849, '<td valign="top">Lovely lighting!</td>', 'Lovely lighting!', '2008-01-13 14:59:38.000000', NULL, 1),
(4389249, 628845, 83313, '<td valign="top">Awwwww!!! How can I not like a picture of a baby with glasses!?</td>', 'Awwwww!!! How can I not like a picture of a baby with glasses!?', '2008-01-13 15:00:26.000000', NULL, 1),
(4389251, 629214, 83313, '<td valign="top">Quit staring me down while I try to vote! It won''t help!<br/> <br/>Other than the top of your head being slightly cut off (which, given the care that went into his picture, I think was intentional), I like this. Good color and clarity, nice lighting usage.</td>', 'Quit staring me down while I try to vote! It won''t help! Other than the top of your head being slightly cut off (which, given the care that went into his picture, I think was intentional), I like this. Good color and clarity, nice lighting usage.', '2008-01-13 15:03:26.000000', NULL, 1),
(4389264, 629988, 83313, '<td valign="top">Very cute and good lighting. I do need to put on the uniform of the JPEG police for a moment... (Ahem, don''t look while I change.)<br/> <br/>There is some compression artifacting visible, mostly around the glasses, but a touch around the lips and teeth as well. There is also a bright spot on her upper right cheek, just under the corner of the glasses. I''m not sure if that is JPEG artifacts or from light refraction through the glasses. Looking at your file size, you only used about half the file size that was available to you. You can use less compression and eliminate a lot of those artifacts. Alway use the lowest compression ration that will get your shot in under the filesize limit for a challenge.</td>', 'Very cute and good lighting. I do need to put on the uniform of the JPEG police for a moment... (Ahem, don''t look while I change.) There is some compression artifacting visible, mostly around the glasses, but a touch around the lips and teeth as well. There is also a bright spot on her upper right cheek, just under the corner of the glasses. I''m not sure if that is JPEG artifacts or from light refraction through the glasses. Looking at your file size, you only used about half the file size that was available to you. You can use less compression and eliminate a lot of those artifacts. Alway use the lowest compression ration that will get your shot in under the filesize limit for a challenge.', '2008-01-13 15:10:26.000000', NULL, 1),
(4389267, 630544, 58247, '<td valign="top">Nice focus, but I''ll be honest and say that the lose hairs do bother me some. But not enough to not give this a good score. :-)</td>', 'Nice focus, but I''ll be honest and say that the lose hairs do bother me some. But not enough to not give this a good score. :-)', '2008-01-13 15:11:20.000000', NULL, 1),
(4389268, 630503, 83313, '<td valign="top">Nice use of perspective, but she was very close and the flash washed out alot of the details n her face.</td>', 'Nice use of perspective, but she was very close and the flash washed out alot of the details n her face.', '2008-01-13 15:11:24.000000', NULL, 1),
(4389269, 630805, 58247, '<td valign="top">Nice lighting.</td>', 'Nice lighting.', '2008-01-13 15:12:37.000000', NULL, 1),
(4389270, 630707, 83313, '<td valign="top">Softening the image may have made it a little more flattering, but the smile is great and really makes it.</td>', 'Softening the image may have made it a little more flattering, but the smile is great and really makes it.', '2008-01-13 15:12:47.000000', NULL, 1),
