(4389934, 630697, 60354, '<td valign="top">Beautiful silhouette!</td>', 'Beautiful silhouette!', '2008-01-13 21:45:40.000000', NULL, 1),
(4389935, 630795, 60354, '<td valign="top">Nice expression! Really like how the desaturated tones add to the slightly demented mood of the image. What was the lighting setup? Just a single softbox?</td>', 'Nice expression! Really like how the desaturated tones add to the slightly demented mood of the image. What was the lighting setup? Just a single softbox?', '2008-01-13 21:47:27.000000', NULL, 1),
(4389947, 630805, 60354, '<td valign="top">Well executed! The harsh shadows juxtaposed with the subtle facial expression really make this shot stand out from the bunch.  I hope you can share your magic lighting setup!</td>', 'Well executed! The harsh shadows juxtaposed with the subtle facial expression really make this shot stand out from the bunch.  I hope you can share your magic lighting setup!', '2008-01-13 21:50:54.000000', NULL, 1),
(4389985, 630714, 63269, '<td valign="top">It might be ineresting to shoot this with a different, more interesting setting - perhaps seating the subject at a desk or at a library or something would have made this more interesting... I don''t know. Just a thought! :) I like the idea you have here though.</td>', 'It might be ineresting to shoot this with a different, more interesting setting - perhaps seating the subject at a desk or at a library or something would have made this more interesting... I don''t know. Just a thought! :) I like the idea you have here though.', '2008-01-13 22:12:15.000000', NULL, 1),
