(4391142, 630665, 82022, '<td valign="top">Very cute!</td>', 'Very cute!', '2008-01-14 11:28:47.000000', NULL, 1),
(4391145, 629778, 63269, '<td valign="top">I love the high-contrast here, and the extreme sharpening here gives it a very interesting effect. I''m guessing you''ve probably gotten a ton of comments saying it''s too sharpened, but I personally actually think it''s neat. ;) A 6 from me.</td>', 'I love the high-contrast here, and the extreme sharpening here gives it a very interesting effect. I''m guessing you''ve probably gotten a ton of comments saying it''s too sharpened, but I personally actually think it''s neat. ;) A 6 from me.', '2008-01-14 11:35:04.000000', NULL, 1),
(4391149, 629969, 63269, '<td valign="top">Nicely done - the shallow DOF works great here. I personally think that maybe moving the camera to an angle towards her face might have increased the shallow DOF effect and made the composition more interesting. Just a thought. :)</td>', 'Nicely done - the shallow DOF works great here. I personally think that maybe moving the camera to an angle towards her face might have increased the shallow DOF effect and made the composition more interesting. Just a thought. :)', '2008-01-14 11:37:04.000000', NULL, 1),
(4391152, 630778, 63269, '<td valign="top">I like how the colors and vague shapes of the background work with the rest of the shot. I personally would brighten the face up just a bit more, but otherwise this is excellent.</td>', 'I like how the colors and vague shapes of the background work with the rest of the shot. I personally would brighten the face up just a bit more, but otherwise this is excellent.', '2008-01-14 11:38:21.000000', NULL, 1),
