(4395128, 630448, 40155, '<td valign="top">Very creative.  I like the way you got around the glare issue.</td>', 'Very creative.  I like the way you got around the glare issue.', '2008-01-15 23:17:51.000000', NULL, 1),
(4395129, 630637, 40155, '<td valign="top">Who notices the glasses?</td>', 'Who notices the glasses?', '2008-01-15 23:18:12.000000', NULL, 1),
(4395130, 630330, 49763, '<td valign="top">Psychodelic.</td>', 'Psychodelic.', '2008-01-15 23:18:34.000000', NULL, 1),
(4395131, 628605, 40155, '<td valign="top">I really don''t think your dog could see much out of those but just for the fact that he posed with it on. 8.</td>', 'I really don''t think your dog could see much out of those but just for the fact that he posed with it on. 8.', '2008-01-15 23:18:51.000000', NULL, 1),
(4395133, 630756, 49763, '<td valign="top">Nice colors and composition.</td>', 'Nice colors and composition.', '2008-01-15 23:19:05.000000', NULL, 1),
(4395137, 630701, 40155, '<td valign="top">I know you. I mean I know ME. I''ve seen you somewhere. Or maybe it''s just the vest? :-)</td>', 'I know you. I mean I know ME. I''ve seen you somewhere. Or maybe it''s just the vest? :-)', '2008-01-15 23:19:38.000000', NULL, 1),
(4395139, 630740, 33400, '<td valign="top">This is a wonderful picture of time and experience.  The expression says gentle wisdom.<br/> <br/>Very well done.</td>', 'This is a wonderful picture of time and experience.  The expression says gentle wisdom. Very well done.', '2008-01-15 23:19:58.000000', NULL, 1),
(4395144, 630631, 40155, '<td valign="top">Very nice. The light was a little bright.  I''ve never seen teeth gleam like that before!</td>', 'Very nice. The light was a little bright.  I''ve never seen teeth gleam like that before!', '2008-01-15 23:20:20.000000', NULL, 1),
(4395145, 630785, 49763, '<td valign="top">Not a bad shot.</td>', 'Not a bad shot.', '2008-01-15 23:20:22.000000', NULL, 1),
(4395149, 630778, 49763, '<td valign="top">I honestly like the title better than the image.</td>', 'I honestly like the title better than the image.', '2008-01-15 23:21:11.000000', NULL, 1),
(4395150, 630613, 40155, '<td valign="top">The lense to the right seems to have an object like a feather on it.  Maybe a reflexion.  And I love the colours your model wore.</td>', 'The lense to the right seems to have an object like a feather on it.  Maybe a reflexion.  And I love the colours your model wore.', '2008-01-15 23:21:28.000000', NULL, 1),
(4395152, 630799, 40155, '<td valign="top">Hey I think you got glare, man!  he he !</td>', 'Hey I think you got glare, man!  he he !', '2008-01-15 23:21:48.000000', NULL, 1),
(4395154, 629552, 49763, '<td valign="top">I feel the same way.</td>', 'I feel the same way.', '2008-01-15 23:22:27.000000', NULL, 1),
(4395155, 630030, 40155, '<td valign="top">Good but the shapes in the background distract me.  I almost expect something to pop out of the shadows.</td>', 'Good but the shapes in the background distract me.  I almost expect something to pop out of the shadows.', '2008-01-15 23:22:45.000000', NULL, 1),
(4395157, 630432, 49763, '<td valign="top">That is a really interesting book he is holding. This is a very high quality image.</td>', 'That is a really interesting book he is holding. This is a very high quality image.', '2008-01-15 23:23:16.000000', NULL, 1),
(4395158, 630325, 40155, '<td valign="top">Great photo.  I love the composition.</td>', 'Great photo.  I love the composition.', '2008-01-15 23:23:35.000000', NULL, 1),
(4395159, 629197, 49763, '<td valign="top">You have cut off the top of her head.</td>', 'You have cut off the top of her head.', '2008-01-15 23:24:08.000000', NULL, 1),
(4395160, 630279, 40155, '<td valign="top">I like it very much.</td>', 'I like it very much.', '2008-01-15 23:24:32.000000', NULL, 1),
(4395166, 630628, 49763, '<td valign="top">I laughed when I saw this one. Trust me, that''s a good thing.</td>', 'I laughed when I saw this one. Trust me, that''s a good thing.', '2008-01-15 23:25:06.000000', NULL, 1),
(4395167, 629953, 40155, '<td valign="top">Not sure what to make with the huge flower covering half the model''s face. There is also a less desirable reflection of the flower in the lens.</td>', 'Not sure what to make with the huge flower covering half the model''s face. There is also a less desirable reflection of the flower in the lens.', '2008-01-15 23:25:33.000000', NULL, 1),
(4395169, 630470, 49763, '<td valign="top">I don''t know what you were attempting with this picture.</td>', 'I don''t know what you were attempting with this picture.', '2008-01-15 23:25:40.000000', NULL, 1),
(4395170, 629702, 40155, '<td valign="top">Nice portrait.  Wish I could see her eyes but I understand it''s about the moment.</td>', 'Nice portrait.  Wish I could see her eyes but I understand it''s about the moment.', '2008-01-15 23:26:04.000000', NULL, 1),
(4395172, 630646, 49763, '<td valign="top">Your choice of depth of field is interesting and unusually. Good work.</td>', 'Your choice of depth of field is interesting and unusually. Good work.', '2008-01-15 23:26:25.000000', NULL, 1),
(4395173, 629073, 40155, '<td valign="top">Too much shadow over the right eye ( my right, her left).</td>', 'Too much shadow over the right eye ( my right, her left).', '2008-01-15 23:26:42.000000', NULL, 1),
(4395176, 630042, 49763, '<td valign="top">Airtight shot.</td>', 'Airtight shot.', '2008-01-15 23:27:05.000000', NULL, 1),
(4395177, 630748, 40155, '<td valign="top">She is so sweet but those specs can''t really be her size.  I love the DOF.</td>', 'She is so sweet but those specs can''t really be her size.  I love the DOF.', '2008-01-15 23:27:35.000000', NULL, 1),
(4395180, 630735, 49763, '<td valign="top">I think this one is great but what is going on with the white streaks on the left side of the image. I guess you were simply not able to edit them out under the restraints of the rules.</td>', 'I think this one is great but what is going on with the white streaks on the left side of the image. I guess you were simply not able to edit them out under the restraints of the rules.', '2008-01-15 23:28:33.000000', NULL, 1),
(4395182, 630540, 40155, '<td valign="top">Now this is what I want to see.  A true model who does wear specs on a regular basis.  I hope he enjoys his portrait.</td>', 'Now this is what I want to see.  A true model who does wear specs on a regular basis.  I hope he enjoys his portrait.', '2008-01-15 23:29:01.000000', NULL, 1),
(4395184, 629939, 49763, '<td valign="top">This guy is interesting.</td>', 'This guy is interesting.', '2008-01-15 23:29:05.000000', NULL, 1),
(4395186, 628557, 40155, '<td valign="top">Gorgeous model.  Those little bars of light are distracting though. Could you take the same shot and not have the tattle tell sign of lighting?</td>', 'Gorgeous model.  Those little bars of light are distracting though. Could you take the same shot and not have the tattle tell sign of lighting?', '2008-01-15 23:30:08.000000', NULL, 1),
(4395187, 628924, 49763, '<td valign="top">The make up is either over the top or weird enough to be cool. I can''t decide.</td>', 'The make up is either over the top or weird enough to be cool. I can''t decide.', '2008-01-15 23:30:13.000000', NULL, 1),
(4395189, 630792, 49763, '<td valign="top">I like the colors.</td>', 'I like the colors.', '2008-01-15 23:30:31.000000', NULL, 1),
(4395191, 630815, 40155, '<td valign="top">Sorry Elmo but I can''t even make out the reflection.</td>', 'Sorry Elmo but I can''t even make out the reflection.', '2008-01-15 23:30:36.000000', NULL, 1),
(4395192, 630634, 40155, '<td valign="top">Nice try...too much glare.</td>', 'Nice try...too much glare.', '2008-01-15 23:30:58.000000', NULL, 1),
(4395193, 630780, 49763, '<td valign="top">Mr. patatoe head</td>', 'Mr. patatoe head', '2008-01-15 23:31:08.000000', NULL, 1),
(4395195, 630257, 49763, '<td valign="top">The image seems kind of flat in my opinion.</td>', 'The image seems kind of flat in my opinion.', '2008-01-15 23:31:40.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4395196, 628810, 40155, '<td valign="top">Alright.  a bit scary.  you should have been wearing those googles a little earlier on in the week, I think.</td>', 'Alright.  a bit scary.  you should have been wearing those googles a little earlier on in the week, I think.', '2008-01-15 23:31:42.000000', NULL, 1),
(4395198, 630432, 40155, '<td valign="top">I love this portrait.  It''s one to frame.</td>', 'I love this portrait.  It''s one to frame.', '2008-01-15 23:32:06.000000', NULL, 1),
(4395200, 630791, 49763, '<td valign="top">I actually like the softness of this image. It''s fitting.</td>', 'I actually like the softness of this image. It''s fitting.', '2008-01-15 23:32:43.000000', NULL, 1),
(4395203, 629782, 40155, '<td valign="top">Your beautiful model is captivating but what if those glasses were being used?  Could your photography and her beauty still command attention?</td>', 'Your beautiful model is captivating but what if those glasses were being used?  Could your photography and her beauty still command attention?', '2008-01-15 23:33:09.000000', NULL, 1),
(4395204, 630613, 49763, '<td valign="top">Nice but a little too sharp for my taste.</td>', 'Nice but a little too sharp for my taste.', '2008-01-15 23:33:10.000000', NULL, 1),
(4395207, 629214, 49763, '<td valign="top">I would have kept the top of his head in frame if I was you.</td>', 'I would have kept the top of his head in frame if I was you.', '2008-01-15 23:33:44.000000', NULL, 1),
(4395210, 628885, 49763, '<td valign="top">You read Tolkien I see.</td>', 'You read Tolkien I see.', '2008-01-15 23:34:24.000000', NULL, 1),
(4395212, 630714, 40155, '<td valign="top">Sorry the shot is blurry and the colours are dull. Give your model another chance and do it over.</td>', 'Sorry the shot is blurry and the colours are dull. Give your model another chance and do it over.', '2008-01-15 23:34:36.000000', NULL, 1),
(4395214, 629326, 49763, '<td valign="top">As a student I can truly relate. This is a good shot.</td>', 'As a student I can truly relate. This is a good shot.', '2008-01-15 23:35:11.000000', NULL, 1),
(4395215, 630544, 33400, '<td valign="top">This definitely goes in the "unique" category.  The specs seem out of place with the painful texture on the skin.  They''re so clean and smooth.  On the other hand, the face beneath the mud is clearly beautiful and the eyes are quite clear and bright. So maybe it works after all.<br/>Either way, it''s intriguing and I like it.  I hope you do too.</td>', 'This definitely goes in the "unique" category.  The specs seem out of place with the painful texture on the skin.  They''re so clean and smooth.  On the other hand, the face beneath the mud is clearly beautiful and the eyes are quite clear and bright. So maybe it works after all.Either way, it''s intriguing and I like it.  I hope you do too.', '2008-01-15 23:35:19.000000', NULL, 1),
(4395216, 629561, 40155, '<td valign="top">I like it because of the left lens distortion of the background.</td>', 'I like it because of the left lens distortion of the background.', '2008-01-15 23:35:27.000000', NULL, 1),
(4395219, 630633, 49763, '<td valign="top">I would have liked this more had it been less cluttered.</td>', 'I would have liked this more had it been less cluttered.', '2008-01-15 23:35:55.000000', NULL, 1),
(4395222, 628708, 40155, '<td valign="top">Sorry but the shot is blurry, there is glare and I believe you need a bit of colour correction.</td>', 'Sorry but the shot is blurry, there is glare and I believe you need a bit of colour correction.', '2008-01-15 23:36:15.000000', NULL, 1),
(4395223, 630427, 40155, '<td valign="top">Awesome shot.  even more awesome model.  10.</td>', 'Awesome shot.  even more awesome model.  10.', '2008-01-15 23:36:39.000000', NULL, 1),
(4395227, 630270, 40155, '<td valign="top">You caught the twinkle in her eyes! Amazing.  Simple background. Nicely done.</td>', 'You caught the twinkle in her eyes! Amazing.  Simple background. Nicely done.', '2008-01-15 23:37:19.000000', NULL, 1),
(4395228, 629702, 49763, '<td valign="top">Well done. I like how the model is offset to the right.</td>', 'Well done. I like how the model is offset to the right.', '2008-01-15 23:37:27.000000', NULL, 1),
(4395231, 630606, 49763, '<td valign="top">Nice choice of focality.</td>', 'Nice choice of focality.', '2008-01-15 23:37:50.000000', NULL, 1),
(4395235, 630800, 40155, '<td valign="top">I saw the photo and thought, poor kids got them on crooked! So well titled!</td>', 'I saw the photo and thought, poor kids got them on crooked! So well titled!', '2008-01-15 23:38:53.000000', NULL, 1),
(4395236, 630741, 40155, '<td valign="top">Good job.</td>', 'Good job.', '2008-01-15 23:39:05.000000', NULL, 1),
(4395237, 630517, 49763, '<td valign="top">I am slightly interested by the reflection of a guy taking a picture in the glasses as apparently contradicted by the title of the image.</td>', 'I am slightly interested by the reflection of a guy taking a picture in the glasses as apparently contradicted by the title of the image.', '2008-01-15 23:39:21.000000', NULL, 1),
(4395238, 630382, 40155, '<td valign="top">Awesome work.  I wonder if Steve has antiglare.  I can''t figure out how else that shot would have worked.</td>', 'Awesome work.  I wonder if Steve has antiglare.  I can''t figure out how else that shot would have worked.', '2008-01-15 23:39:42.000000', NULL, 1),
(4395239, 630624, 49763, '<td valign="top">I like the tone of the image.</td>', 'I like the tone of the image.', '2008-01-15 23:40:01.000000', NULL, 1),
(4395240, 629394, 49763, '<td valign="top">Clever.</td>', 'Clever.', '2008-01-15 23:40:26.000000', NULL, 1),
(4395241, 630437, 40155, '<td valign="top">Focus seems to be on the cigar and not the specs.</td>', 'Focus seems to be on the cigar and not the specs.', '2008-01-15 23:40:27.000000', NULL, 1),
(4395244, 629208, 40155, '<td valign="top">Great portrait.  While your background is a little busy for my taste, the pose is so natural.</td>', 'Great portrait.  While your background is a little busy for my taste, the pose is so natural.', '2008-01-15 23:41:20.000000', NULL, 1),
(4395247, 630740, 49763, '<td valign="top">This is well done. I am so glad its not balck and white.</td>', 'This is well done. I am so glad its not balck and white.', '2008-01-15 23:41:40.000000', NULL, 1),
(4395248, 629978, 49763, '<td valign="top">Too small.</td>', 'Too small.', '2008-01-15 23:42:01.000000', NULL, 1),
(4395250, 629820, 49763, '<td valign="top">Great concept and well executed.</td>', 'Great concept and well executed.', '2008-01-15 23:42:34.000000', NULL, 1),
(4395251, 630042, 40155, '<td valign="top">Great choice in camera!  It must have been a SP?</td>', 'Great choice in camera!  It must have been a SP?', '2008-01-15 23:43:08.000000', NULL, 1),
(4395254, 630638, 49763, '<td valign="top">This such a cool unified image. I applaud you.</td>', 'This such a cool unified image. I applaud you.', '2008-01-15 23:43:18.000000', NULL, 1),
(4395255, 629063, 49763, '<td valign="top">Well done.</td>', 'Well done.', '2008-01-15 23:43:59.000000', NULL, 1),
(4395256, 630284, 40155, '<td valign="top">Wow, I can see the eyelash on the lens.  Not sure I like the composition but if you had to poke your eye for FX, you get a 7.</td>', 'Wow, I can see the eyelash on the lens.  Not sure I like the composition but if you had to poke your eye for FX, you get a 7.', '2008-01-15 23:44:03.000000', NULL, 1),
(4395257, 629748, 40155, '<td valign="top">Awesome shot but not typical of a portrait style photo.</td>', 'Awesome shot but not typical of a portrait style photo.', '2008-01-15 23:44:33.000000', NULL, 1),
(4395258, 630018, 49763, '<td valign="top">I can see the string.</td>', 'I can see the string.', '2008-01-15 23:44:47.000000', NULL, 1),
(4395259, 629291, 49763, '<td valign="top">It''s not a portrait.</td>', 'It''s not a portrait.', '2008-01-15 23:45:16.000000', NULL, 1),
(4395263, 630665, 49763, '<td valign="top">I''m impressed at the stagging considering we have two dogs here.</td>', 'I''m impressed at the stagging considering we have two dogs here.', '2008-01-15 23:45:59.000000', NULL, 1),
(4395264, 630232, 49763, '<td valign="top">You stayed true to the blue.</td>', 'You stayed true to the blue.', '2008-01-15 23:46:25.000000', NULL, 1),
(4395266, 629930, 49763, '<td valign="top">It appears a little haphazard in my estimation.</td>', 'It appears a little haphazard in my estimation.', '2008-01-15 23:47:50.000000', NULL, 1),
(4395269, 630669, 49763, '<td valign="top">An awkward composition.</td>', 'An awkward composition.', '2008-01-15 23:48:16.000000', NULL, 1),
(4395271, 629865, 33400, '<td valign="top">One extra point for using "askance" and doing so properly.<br/> <br/>Good capture, good crop and lighting.  I wish her eyes were sharper.  It''s really the eyes that make the side-ways glance work here, but the specs got the tighter focus.<br/>There''s something delightful and endearing in her face - playful but determined.  Well shot.</td>', 'One extra point for using "askance" and doing so properly. Good capture, good crop and lighting.  I wish her eyes were sharper.  It''s really the eyes that make the side-ways glance work here, but the specs got the tighter focus.There''s something delightful and endearing in her face - playful but determined.  Well shot.', '2008-01-15 23:48:50.000000', NULL, 1),
(4395272, 629058, 49763, '<td valign="top">This is a very rich image and is well suited to the balck and white medium. Good work.</td>', 'This is a very rich image and is well suited to the balck and white medium. Good work.', '2008-01-15 23:49:20.000000', NULL, 1),
(4395273, 629820, 40155, '<td valign="top">I wanna know how that was done.</td>', 'I wanna know how that was done.', '2008-01-15 23:49:47.000000', NULL, 1),
(4395274, 630519, 49763, '<td valign="top">A well chosen angle but a better chosen shirt.</td>', 'A well chosen angle but a better chosen shirt.', '2008-01-15 23:49:54.000000', NULL, 1),
(4395278, 628845, 49763, '<td valign="top">Combinations of shoftness and detail like this one never fail to amaze me.</td>', 'Combinations of shoftness and detail like this one never fail to amaze me.', '2008-01-15 23:51:04.000000', NULL, 1),
(4395279, 629778, 40155, '<td valign="top">How was this done. It''s bizarre.</td>', 'How was this done. It''s bizarre.', '2008-01-15 23:51:05.000000', NULL, 1),
(4395280, 630448, 49763, '<td valign="top">This is perfect.</td>', 'This is perfect.', '2008-01-15 23:51:34.000000', NULL, 1),
(4395282, 630814, 49763, '<td valign="top">This is frankly boring.</td>', 'This is frankly boring.', '2008-01-15 23:52:05.000000', NULL, 1),
(4395284, 629788, 49763, '<td valign="top">It has been done before.</td>', 'It has been done before.', '2008-01-15 23:52:27.000000', NULL, 1),
(4395285, 630804, 49763, '<td valign="top">Nice colors.</td>', 'Nice colors.', '2008-01-15 23:52:44.000000', NULL, 1),
(4395286, 630278, 49763, '<td valign="top">An interesting expedition into optics.</td>', 'An interesting expedition into optics.', '2008-01-15 23:53:48.000000', NULL, 1),
(4395288, 630409, 49763, '<td valign="top">I like it.</td>', 'I like it.', '2008-01-15 23:54:12.000000', NULL, 1),
