(4395292, 629392, 49763, '<td valign="top">Weird.</td>', 'Weird.', '2008-01-15 23:55:21.000000', NULL, 1),
(4395293, 629743, 49763, '<td valign="top">Your composition could use some work; perhaps not so close up.</td>', 'Your composition could use some work; perhaps not so close up.', '2008-01-15 23:56:10.000000', NULL, 1),
(4395295, 630702, 49763, '<td valign="top">I am a little interested thus you don''t get a one.</td>', 'I am a little interested thus you don''t get a one.', '2008-01-15 23:56:57.000000', NULL, 1),
(4395297, 629865, 49763, '<td valign="top">That''s quite an expression you have captured here. I like this.</td>', 'That''s quite an expression you have captured here. I like this.', '2008-01-15 23:57:26.000000', NULL, 1),
