(4395334, 630168, 83313, '<td valign="top">Great showing here. This deserved placing high. I think it should have been even higher, I had given it a 9.<br/><br/><i>Message edited by author 2008-01-16 00:07:25.</i></td>', 'Great showing here. This deserved placing high. I think it should have been even higher, I had given it a 9.', '2008-01-16 00:07:03.000000', '2008-01-16 00:07:25.000000', 0),
