(4396164, 630770, 23484, '<td valign="top">Ahhh, so you''re going for humor now. Decided to take a break from spooky. Nice job Colleen.</td>', 'Ahhh, so you''re going for humor now. Decided to take a break from spooky. Nice job Colleen.', '2008-01-16 08:16:41.000000', NULL, 0),
(4396166, 630813, 49804, '<td valign="top">I thought this was yours, considering it is a self portrait that wouldn''t be too hard for me to figure out, but I actually gave this one a 7 during voting, congrats on it getting bumped up above a 6.</td>', 'I thought this was yours, considering it is a self portrait that wouldn''t be too hard for me to figure out, but I actually gave this one a 7 during voting, congrats on it getting bumped up above a 6.', '2008-01-16 08:17:04.000000', NULL, 0),
