(4488755, 629207, 42181, '<td valign="top">Good looking shot, i used to swim for my county so this really appeals to me.<br/>You have really captured that moment of thought where he is running though his head "stokes", "breathing", winning.<br/></td>', 'Good looking shot, i used to swim for my county so this really appeals to me.You have really captured that moment of thought where he is running though his head "stokes", "breathing", winning.', '2008-02-15 12:48:44.000000', NULL, 0),
(4491907, 630810, 64670, '<td valign="top">Classic image - gave this a 9 - thought it ROCKED!</td>', 'Classic image - gave this a 9 - thought it ROCKED!', '2008-02-17 02:07:54.000000', NULL, 0),
(4496787, 630724, 30982, '<td valign="top">Heh!  I love the look.  I use onboard flash when I''m shooting stuff that folks at work ask me to shoot (parties, meetings, ceremonies - odd stuff like that) and oddly, no one ever comes back to tell me that the flash was too harsh.  :-)  But for "professional" stuff, or to improve skills, onboard camera flash is generally not recommended (though it does work somewhat well as fill flash outside).  I find it hard to light people well without all the fancy doo-dads that the portrait folks use, but natural window light if you have it works well, and a simple reflector of white posterboard if it''s handy will fill in on the side opposite the window.  It looks dorky, but it works.  I''ve been trying it with cats, which is a bit harder since they refuse to sit still, but that''s neither here nor there.  Anyway, I think you met the challenge well and caught an excellent expression!</td>', 'Heh!  I love the look.  I use onboard flash when I''m shooting stuff that folks at work ask me to shoot (parties, meetings, ceremonies - odd stuff like that) and oddly, no one ever comes back to tell me that the flash was too harsh.  :-)  But for "professional" stuff, or to improve skills, onboard camera flash is generally not recommended (though it does work somewhat well as fill flash outside).  I find it hard to light people well without all the fancy doo-dads that the portrait folks use, but natural window light if you have it works well, and a simple reflector of white posterboard if it''s handy will fill in on the side opposite the window.  It looks dorky, but it works.  I''ve been trying it with cats, which is a bit harder since they refuse to sit still, but that''s neither here nor there.  Anyway, I think you met the challenge well and caught an excellent expression!', '2008-02-19 03:32:40.000000', NULL, 0),
(4512241, 629650, 49804, '<td valign="top">Very nice natural lighting, probably didn''t score well because it isn''t very crisp and sharp, but other than that, a great shot.</td>', 'Very nice natural lighting, probably didn''t score well because it isn''t very crisp and sharp, but other than that, a great shot.', '2008-02-24 15:50:08.000000', NULL, 0),
(4519284, 630558, 67145, '<td valign="top">another brilliant idea and photograph . excellent ... love the processing .. so sharp and clean ... if she''s your daughter .. LUCKY YOU !! .. she''s gorgeous and extremely photogenic .. :)</td>', 'another brilliant idea and photograph . excellent ... love the processing .. so sharp and clean ... if she''s your daughter .. LUCKY YOU !! .. she''s gorgeous and extremely photogenic .. :)', '2008-02-26 20:06:29.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4524066, 630240, 60862, '<td valign="top">Very sweet portrait, Cindi!</td>', 'Very sweet portrait, Cindi!', '2008-02-28 00:52:24.000000', NULL, 0),
(4528591, 630810, 73056, '<td valign="top">What a shot! What a cutie!</td>', 'What a shot! What a cutie!', '2008-02-29 18:27:32.000000', NULL, 0),
(4533707, 630773, 60862, '<td valign="top">Brian, I think the composition and pose are both nice.  My guess about the score is that the hat and shirt are so dark as to basically punch visual holes in the image. Black is tough to light well enough to get a little texture or shape to it, so it comes off very two-dimensional.</td>', 'Brian, I think the composition and pose are both nice.  My guess about the score is that the hat and shirt are so dark as to basically punch visual holes in the image. Black is tough to light well enough to get a little texture or shape to it, so it comes off very two-dimensional.', '2008-03-02 23:00:32.000000', NULL, 0),
(4533711, 630232, 60862, '<td valign="top">I like the pose a lot.  I agree with the other commenters about the blue cast on the lower part of her face, but I think it''s a minor issue.  Another minor point is her hand under her head is a little overexposed.  But overall, a nice shot!</td>', 'I like the pose a lot.  I agree with the other commenters about the blue cast on the lower part of her face, but I think it''s a minor issue.  Another minor point is her hand under her head is a little overexposed.  But overall, a nice shot!', '2008-03-02 23:02:17.000000', NULL, 0),
(4533727, 629058, 60862, '<td valign="top">Funny shot!  I think it''d have even more impact if you cropped out the left side (so the left edge is just inside the frame of the painting) and the computer.  It''d look like he''s looking at the cat instead of the computer, but he and the cat would be much larger in the frame.</td>', 'Funny shot!  I think it''d have even more impact if you cropped out the left side (so the left edge is just inside the frame of the painting) and the computer.  It''d look like he''s looking at the cat instead of the computer, but he and the cat would be much larger in the frame.', '2008-03-02 23:17:47.000000', NULL, 0),
(4533729, 630770, 60862, '<td valign="top">Funny shot!</td>', 'Funny shot!', '2008-03-02 23:18:38.000000', NULL, 0),
(4533730, 628990, 60862, '<td valign="top">Funny idea, well shot.  I think there''s just a bit too much book in it for my taste and not enough of her face.</td>', 'Funny idea, well shot.  I think there''s just a bit too much book in it for my taste and not enough of her face.', '2008-03-02 23:20:49.000000', NULL, 0),
(4533733, 629727, 60862, '<td valign="top">A perfectly nice shot.  His face is set of well from the dark background and his shirt.  No clue on the score.</td>', 'A perfectly nice shot.  His face is set of well from the dark background and his shirt.  No clue on the score.', '2008-03-02 23:21:50.000000', NULL, 0),
(4533740, 629684, 60862, '<td valign="top">Kelli, I think this is a very nice portrait.  Yes it''s not razor sharp, and I suppose that might have improved it.  But the lighting''s very soft and pleasant, the pose is interesting, and I like the composition.</td>', 'Kelli, I think this is a very nice portrait.  Yes it''s not razor sharp, and I suppose that might have improved it.  But the lighting''s very soft and pleasant, the pose is interesting, and I like the composition.', '2008-03-02 23:25:03.000000', NULL, 0),
(4533746, 630076, 60862, '<td valign="top">Terrific shot, Michelle!  The lighting, composition, pose, and his expression are all right on.  No idea why the voters didn''t go higher.  But look at the commenter average! :)</td>', 'Terrific shot, Michelle!  The lighting, composition, pose, and his expression are all right on.  No idea why the voters didn''t go higher.  But look at the commenter average! :)', '2008-03-02 23:26:40.000000', NULL, 0),
(4533748, 630772, 60862, '<td valign="top">Great lighting, pose, and half-smile.  Her hair makes a great frame, too.  Yes, it could''ve been a little sharper, but that''s minor.</td>', 'Great lighting, pose, and half-smile.  Her hair makes a great frame, too.  Yes, it could''ve been a little sharper, but that''s minor.', '2008-03-02 23:28:00.000000', NULL, 0),
(4533763, 630638, 60862, '<td valign="top">I like the wavelets echoing your tweed hat.  I also like the setting, but I think a portrait crop might''ve served you better.</td>', 'I like the wavelets echoing your tweed hat.  I also like the setting, but I think a portrait crop might''ve served you better.', '2008-03-02 23:30:23.000000', NULL, 0),
(4533782, 630706, 60862, '<td valign="top">A lot of character in his face, Catherine.  His shirt''s a bit too dark for my monitor - kind of becomes a black hole.</td>', 'A lot of character in his face, Catherine.  His shirt''s a bit too dark for my monitor - kind of becomes a black hole.', '2008-03-02 23:32:56.000000', NULL, 0),
(4533798, 629093, 60862, '<td valign="top">Peter, I''m not sure what you were going for.  Maybe that was your point. :)</td>', 'Peter, I''m not sure what you were going for.  Maybe that was your point. :)', '2008-03-02 23:34:53.000000', NULL, 0),
